import Foundation

// Base64-encoded .tgs (gzip-compressed Lottie) duck animations, embedded directly
// in the binary (no Bazel resource wiring). Decoded once at runtime and played via
// the real RLottie pipeline (AnimatedStickerNode). Source .tgs live in
// AorusGram/Animations/ for reference. If a string ever fails to decode the player
// simply shows nothing (no crash, no fallback image).
enum SubscriptionAnimationAssets {
    static let outdated = ""

    static let trial = ""
    static let expired = ""
    static let purchase = ""
    // Small banner icons (entry notification).
    static let fire = ""
    static let boost = ""
    // Activation confirmation ducks.
    static let confirm = ""
    static let error = ""
}
